import{c as l,$ as r,Q as s,j as n,g as e,o as i,n as a,m as d}from"./chunks/framework.Ce_49mA8.js";const x=JSON.parse('{"title":"Глобальные настройки","description":"Язык интерфейса, валюта учета, цветовые темы, подключение нейросетей со своим ключом и аварийный сброс данных в ОмниКрафт ЕРП.","frontmatter":{"title":"Глобальные настройки","description":"Язык интерфейса, валюта учета, цветовые темы, подключение нейросетей со своим ключом и аварийный сброс данных в ОмниКрафт ЕРП.","order":16,"datePublished":"2026-11-14","dateModified":"2026-11-19"},"headers":[],"relativePath":"ru/docs/global-settings.md","filePath":"ru/docs/global-settings.md","lastUpdated":1795046400000}'),g={name:"ru/docs/global-settings.md"},c={id:"глобальные-настроики-системы-интерфеис-искусственныи-интеллект-и-безопасность",tabindex:"-1"};function h(p,t,u,m,_,b){const o=r("DocIcon");return s(),n("div",null,[e("h1",c,[i(o,{name:"settings"}),t[0]||(t[0]=a(" Глобальные настройки системы: Интерфейс, Искусственный интеллект и Безопасность ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#глобальные-настроики-системы-интерфеис-искусственныи-интеллект-и-безопасность","aria-label":'Permalink to "Глобальные настройки системы: Интерфейс, Искусственный интеллект и Безопасность"'},"​",-1))]),t[2]||(t[2]=d('<p>В отличие от настроек конкретного рабочего пространства, где мастер определяет параметры цеховой экономики (почасовую ставку, базовую наценку и статьи накладных расходов), <strong>Глобальные настройки системы</strong> задают фундаментальные правила функционирования всего программного комплекса и локальной базы данных.</p><p>Чтобы открыть окно конфигурации, выберите в главном меню программы пункт <strong>«Файл» ➔ «Настройки программы»</strong>. Параметры разделены на две функциональные вкладки: <strong>«Основные»</strong> и <strong>«ИИ-Агент»</strong>.</p><hr><h2 id="вкладка-«основные»" tabindex="-1">Вкладка «Основные» <a class="header-anchor" href="#вкладка-«основные»" aria-label="Permalink to &quot;Вкладка «Основные»&quot;">​</a></h2><p>В этой секции собраны базовые параметры рабочей среды, правила отображения финансовой отчетности, визуальный стиль интерфейса и системная диагностика.</p><h3 id="_1-язык-интерфеиса" tabindex="-1">1. Язык интерфейса <a class="header-anchor" href="#_1-язык-интерфеиса" aria-label="Permalink to &quot;1. Язык интерфейса&quot;">​</a></h3><p>Программный комплекс поддерживает полноценную двуязычную локализацию. При первом запуске система автоматически определяет язык вашей операционной системы и адаптирует отображение элементов.</p><p>Мастер может в любой момент переключить рабочий язык: в списке доступны варианты <strong>«Русский»</strong> и <strong>«English»</strong>:</p><ul><li><strong>Механика применения:</strong> Смена языка требует полного перезапуска приложения. Это необходимо, чтобы все системные окна, формы ввода, иерархия категорий движения денежных средств и встроенные валидаторы корректно выгрузились из оперативной памяти и заново прочитали системные словари.</li></ul><h3 id="_2-валюта-учета" tabindex="-1">2. Валюта учета <a class="header-anchor" href="#_2-валюта-учета" aria-label="Permalink to &quot;2. Валюта учета&quot;">​</a></h3><p>По умолчанию система считывает символ национальной валюты из региональных стандартов операционной системы (например, <code>₽</code>, <code>$</code>, <code>€</code>, <code>₸</code>, <code>₺</code>, <code>Br</code>). Для выбора другой денежной единицы предусмотрено поле со встроенным поиском: нажмите на поле с текущим символом и начните вводить название или международный трехбуквенный код валюты (например, <em>лира</em>, <em>юань</em>, <em>USD</em>, <em>KZT</em>).</p><div class="warning custom-block"><p class="custom-block-title">Защита исторических проводок</p><p>Кнопка смены валюты <strong>автоматически блокируется</strong>, как только в базе данных появляется хотя бы одна фактическая операция: закупка сырья, накладная на оборудование, выпуск партии изделий или кассовый ордер.</p><p>Этот барьер защищает финансовую отчетность. Если бы программа позволяла произвольно менять валюту учета задним числом, все ранее рассчитанные партии готовой продукции, балансы кассы и графики управленческой аналитики мгновенно потеряли бы математический смысл.</p></div><div class="tip custom-block"><p class="custom-block-title">Порядок действий при релокации бизнеса</p><p>Если мастер переносит мастерскую в другую страну и переходит на расчеты в новой валюте, необходимо выполнить процедуру <strong>«Сброс учета»</strong> (см. раздел аварийного обслуживания ниже). Это позволит начать книги учета в новой валюте с чистого листа, полностью сохранив каталог оборудования, базу сырья, технологические рецепты и карточки услуг.</p></div><h3 id="_3-оформление-и-цветовая-палитра" tabindex="-1">3. Оформление и цветовая палитра <a class="header-anchor" href="#_3-оформление-и-цветовая-палитра" aria-label="Permalink to &quot;3. Оформление и цветовая палитра&quot;">​</a></h3><p>Для комфортной многочасовой работы мастера при любом освещении в программе предусмотрен гибкий механизм визуальных тем:</p><ul><li><strong>Режим темы («Тема оформления»):</strong><ul><li><strong>«Системная (авто)»</strong> — приложение синхронизирует светлый или тёмный режим с системной темой операционной системы;</li><li><strong>«Светлая»</strong> — постоянная светлая тема с контрастной графикой для работы при ярком дневном свете;</li><li><strong>«Тёмная»</strong> — глубокая тёмная палитра, снижающая зрительную нагрузку при вечерней работе в студии.</li></ul></li><li><strong>Цветовые пресеты:</strong> В дополнение к общему режиму мастер может выбрать фирменный акцентный оттенок интерфейса. Доступно 10 выверенных палитр: <em>«Автоматический»</em>, <em>«Северная мята»</em>, <em>«Глубокий океан»</em>, <em>«Хвойный бор»</em>, <em>«Тёплый янтарь»</em>, <em>«Пряный терракот»</em>, <em>«Дикая вишня»</em>, <em>«Лавандовый туман»</em>, <em>«Дымчатый кварц»</em> и <em>«Космический обсидиан»</em>.</li><li><strong>Раздельная настройка:</strong> При выборе системного режима в окне отображаются сразу два выпадающих списка — для светлого и тёмного оформления, позволяя заранее настроить любимый акцент для каждого времени суток.</li></ul><h3 id="_4-канал-обновлении-программы" tabindex="-1">4. Канал обновлений программы <a class="header-anchor" href="#_4-канал-обновлении-программы" aria-label="Permalink to &quot;4. Канал обновлений программы&quot;">​</a></h3><p>Селектор <strong>«Канал обновлений»</strong> определяет, из какого источника программа запрашивает пакеты модернизации:</p><ul><li><strong>«Стабильный»</strong> — официальные проверенные релизы, прошедшие полный цикл тестирования. Рекомендован для повседневного коммерческого учета.</li><li><strong>«Бета (Пре-релизы)»</strong> — предрелизные сборки с новыми инструментами и ранними улучшениями для пользователей, желающих первыми тестировать свежие возможности.</li><li><strong>«Альфа (Режим разработчика)»</strong> — специальный канал с самыми свежими инженерными сборками ядра. Данный канал доступен владельцам расширенной лицензии уровня PRO+ и разработчикам.</li></ul><h3 id="_5-диагностика-и-стабильность" tabindex="-1">5. Диагностика и стабильность <a class="header-anchor" href="#_5-диагностика-и-стабильность" aria-label="Permalink to &quot;5. Диагностика и стабильность&quot;">​</a></h3><ul><li><strong>«Отправлять анонимную статистику и отчеты об ошибках»:</strong> Флажок активирует отправку безымянных отчетов об исключительных ситуациях разработчикам. Пакет диагностики содержит исключительно техническую трассировку сбоя и версию операционной системы; коммерческие данные, суммы, названия сырья и клиентские контакты никогда не включаются в журнал.</li><li><strong>«Отправлять отчеты из режима разработки»:</strong> Дополнительный переключатель для специалистов, запускающих программу из исходного кода или использующих сборку с правами разработчика.</li></ul><hr><h2 id="вкладка-«ии-агент»" tabindex="-1">Вкладка «ИИ-Агент» <a class="header-anchor" href="#вкладка-«ии-агент»" aria-label="Permalink to &quot;Вкладка «ИИ-Агент»&quot;">​</a></h2><p>ОмниКрафт ЕРП предоставляет практический интеллектуальный контур на базе нейросетей. Интеграция построена по модели <strong>прямого личного ключа</strong>: пользователь подключает собственный ключ доступа к выбранной языковой модели без серверов-посредников.</p><p>Все запросы направляются <strong>напрямую с вашего рабочего компьютера</strong> на сервера выбранного поставщика. Ваши коммерческие показатели, технологические карты, себестоимость и клиентские базы данных остаются строго конфиденциальными.</p><h3 id="_1-поддерживаемые-поставщики-неиросетеи" tabindex="-1">1. Поддерживаемые поставщики нейросетей <a class="header-anchor" href="#_1-поддерживаемые-поставщики-неиросетеи" aria-label="Permalink to &quot;1. Поддерживаемые поставщики нейросетей&quot;">​</a></h3><p>В окне настроек доступен выбор ведущих мировых провайдеров искусственного интеллекта:</p><ul><li><strong>OpenAI</strong> (<code>gpt-4o</code>, <code>gpt-4o-mini</code>, <code>o1</code>, <code>o3-mini</code>);</li><li><strong>DeepSeek</strong> (<code>deepseek-chat</code>, <code>deepseek-reasoner</code>);</li><li><strong>Google Gemini</strong> (<code>gemini-1.5-flash</code>, <code>gemini-1.5-pro</code>, <code>gemini-2.0</code>);</li><li><strong>Anthropic</strong> (<code>claude-3-5-sonnet</code>, <code>claude-3-5-haiku</code>, <code>claude-3-opus</code>);</li><li><strong>OpenRouter</strong> (универсальный доступ к десяткам мировых моделей через единый баланс);</li><li><strong>Ollama (Локально)</strong> (<code>llama3.2</code>, <code>qwen2.5</code>, <code>mistral</code>, <code>deepseek-r1:8b</code> — стандартный адрес <code>http://localhost:11434/v1</code>, личный ключ не требуется);</li><li><strong>LM Studio (Локально)</strong> (стандартный адрес <code>http://localhost:1234/v1</code>, ключ не требуется);</li><li><strong>Собственный шлюз (<code>Custom</code>)</strong> — любые локальные серверы и корпоративные шлюзы с совместимым протоколом.</li></ul><p>Окно конфигурации обеспечивает максимальное удобство настройки:</p><ul><li><strong>Изолированное сохранение параметров:</strong> Каждый поставщик сохраняет собственную связку «модель — адрес — ключ». При переключении поставщиков сохраненные данные других сервисов не затираются.</li><li><strong>Быстрый переход в консоль:</strong> Рядом с полем ввода ключа расположена прямая ссылка для перехода на страницу генерации ключа в официальной консоли выбранного сервиса.</li><li><strong>Автоматическая диагностика:</strong> При сохранении система проверяет доступность узла и выводит четкий индикатор готовности к работе.</li></ul><h3 id="_2-аппаратная-криптографическая-защита-ключеи" tabindex="-1">2. Аппаратная криптографическая защита ключей <a class="header-anchor" href="#_2-аппаратная-криптографическая-защита-ключеи" aria-label="Permalink to &quot;2. Аппаратная криптографическая защита ключей&quot;">​</a></h3><p>Ключи доступа к нейросетям сохраняются на диске в зашифрованном виде с применением встроенной криптографической подсистемы операционной системы Windows. Ключ привязывается к учетной записи текущего пользователя и аппаратному профилю материнской платы и процессора.</p><p>Даже если злоумышленник скопирует файл конфигурации программы, расшифровать ключ на другом компьютере технически невозможно. При переносе базы на новый компьютер срабатывает встроенный защитный контур, деликатно запрашивая повторный ввод ключа без сбоев программы.</p><h3 id="_3-инструменты-мастера-в-интерфеисе-программы" tabindex="-1">3. Инструменты мастера в интерфейсе программы <a class="header-anchor" href="#_3-инструменты-мастера-в-интерфеисе-программы" aria-label="Permalink to &quot;3. Инструменты мастера в интерфейсе программы&quot;">​</a></h3><p>При подключении нейросети в интерфейсе активируются прикладные кнопки экспресс-анализа с символом искры:</p><ul><li><strong>Калькулятор тиража:</strong> Экспресс-аудит экономической структуры изделия, выявление главного источника издержек и подсказки по безопасной оптимизации цены партии.</li><li><strong>Склад сырья:</strong> Генерация профессионального описания материала, физико-химических характеристик и правил цехового хранения за считанные секунды.</li><li><strong>Верстак производства:</strong> Создание краткой технологической карты мастера с контрольными точками брака и сырьевыми рисками.</li></ul><h3 id="_4-выдвижная-панель-персонального-ассистента" tabindex="-1">4. Выдвижная панель персонального ассистента <a class="header-anchor" href="#_4-выдвижная-панель-персонального-ассистента" aria-label="Permalink to &quot;4. Выдвижная панель персонального ассистента&quot;">​</a></h3><p>С правой стороны главного окна расположена компактная вертикальная полоса шириной 38 пикселей. При нажатии на неё разворачивается рабочий стол персонального цифрового помощника:</p><ul><li><strong>Контекст экрана («карта + детали по запросу»):</strong> Помощник видит активный экран программы (Склад, Верстак, Калькулятор, Продажи) и отвечает с учетом реальных остатков. Вы можете в любой момент отключить передачу контекста тумблером в шапке панели или нажать на значок глаза для проверки отправляемых данных.</li><li><strong>Селектор зоны охвата:</strong> Переключатель режимов «Вкладка» (строгая изоляция действий рамками текущего экрана) и «Вся система» (сквозной доступ к инструментам всех разделов).</li><li><strong>Принцип подтверждения человеком:</strong> Помощник не имеет права изменять данные втайне от мастера. Любая мутирующая операция формирует наглядную интерактивную карточку с кнопками <strong>«Выполнить»</strong> и <strong>«Отклонить»</strong>.</li><li><strong>Чтение внешней сети:</strong> Ассистент умеет выполнять безопасный поиск рыночных цен на сырье, характеристик оборудования и официальных курсов валют без необходимости ручного подтверждения запросов на чтение.</li><li><strong>Бейдж офлайн-контура:</strong> При переключении на локальную модель (<code>Ollama</code>, <code>LM Studio</code>) отображается зеленый защитный щит «Локальная модель / Офлайн», подтверждающий, что коммерческие данные не покидают компьютер мастера.</li></ul><h3 id="_5-глобальные-инструкции-и-цеховои-манифест" tabindex="-1">5. Глобальные инструкции и цеховой манифест <a class="header-anchor" href="#_5-глобальные-инструкции-и-цеховои-манифест" aria-label="Permalink to &quot;5. Глобальные инструкции и цеховой манифест&quot;">​</a></h3><p>Контекст внутреннего ассистента строится по модульному принципу:</p><ul><li><strong>Неизменяемые гарантии ядра:</strong> Фундаментальные математические законы учета (скользящая средняя стоимость сырья МАК, списание партий готовой продукции ФИФО, целочисленное хранение денежных единиц) и политика нулевого разрушения жестко зашиты в ядро программы.</li><li><strong>Настраиваемый манифест мастерской:</strong> В окне настроек доступно текстовое поле для индивидуального манифеста, куда мастер может вписать отраслевые стандарты (допуски на технологический отход, правила упаковки, особенности работы с капризными материалами).</li></ul><h3 id="_6-долговременная-память-на-движке-sqlite-fts5" tabindex="-1">6. Долговременная память на движке SQLite FTS5 <a class="header-anchor" href="#_6-долговременная-память-на-движке-sqlite-fts5" aria-label="Permalink to &quot;6. Долговременная память на движке SQLite FTS5&quot;">​</a></h3><p>Система оснащена встроенным механизмом долговременной памяти на базе локального полнотекстового поискового движка с математическим ранжированием BM25. Помощник запоминает технологические стандарты мастера без сторонних тяжелых библиотек.</p><ul><li><strong>Режимы обучения:</strong> Доступен тумблер автоматического запоминания правил в режиме диалога подтверждения или в фоновом режиме автопилота.</li><li><strong>Контроль объема токенов:</strong> Настраиваемый порог памяти (по умолчанию 1000 токенов). Механизм фонового уплотнения деактивирует устаревшие и наименее надежные записи при приближении к лимиту.</li><li><strong>Обучение на отказах:</strong> При нажатии кнопки <strong>«Отклонить»</strong> на карточке действия открывается диалог указания причины. Зафиксированное замечание мастера сохраняется как постоянное правило для текущей вкладки.</li><li><strong>Закрепление правил (кнопка-булавка):</strong> Позволяет моментально сохранить удачную рекомендацию ассистента в базу знаний.</li><li><strong>Инспектор базы знаний:</strong> Полный реестр выученных правил с возможностью временного отключения переключателем, удаления или добавления новых регламентов вручную.</li><li><strong>Изоляция личных финансов:</strong> Правила пространства «Мой капитал» хранятся изолированно и никогда не передаются в контекст коммерческих производственных разделов.</li></ul><h3 id="_7-взаимодеиствие-с-внешними-агентами-через-протокол-mcp" tabindex="-1">7. Взаимодействие с внешними агентами через протокол MCP <a class="header-anchor" href="#_7-взаимодеиствие-с-внешними-агентами-через-протокол-mcp" aria-label="Permalink to &quot;7. Взаимодействие с внешними агентами через протокол MCP&quot;">​</a></h3><p>ОмниКрафт ЕРП поддерживает международный протокол контекста модели (<code>Model Context Protocol</code>, <code>MCP</code>). Это позволяет подключать внешние среды разработки и агентские клиенты (<code>Cursor</code>, <code>Claude Desktop</code>, <code>Antigravity</code>) напрямую к запущенной программе через локальный межпроцессный канал (<code>stdio</code>).</p><ul><li><strong>Токен сопряжения и моментальный отзыв:</strong> Для безопасного подключения генерируется уникальный криптографический ключ. При необходимости закрыть доступ мастеру достаточно нажать кнопку <strong>«Отозвать токен»</strong>.</li><li><strong>Готовая конфигурация:</strong> По кнопке <strong>«Скопировать JSON-конфиг»</strong> система формирует готовый блок настроек для конфигурационных файлов (<code>claude_desktop_config.json</code> или <code>cursor/mcp.json</code>).</li><li><strong>Доверенный режим:</strong> По умолчанию внешнему агенту разрешены только операции безопасного чтения (<code>read-only</code>). Чтобы агент мог изменять данные (создавать страницы, обновлять описания), необходимо включить переключатель <strong>«Доверенный режим»</strong>.</li><li><strong>Журнал аудита:</strong> Все обращения внешних агентов протоколируются с фиксацией времени вызова, статуса и длительности операции в миллисекундах.</li></ul><p>Ниже приведен справочник команд для управления витриной через внешних агентов:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Задача мастера</th><th style="text-align:left;">Команда протокола</th><th style="text-align:left;">Назначение</th></tr></thead><tbody><tr><td style="text-align:left;">Список доступных витрин</td><td style="text-align:left;"><code>web_store_list_stores</code></td><td style="text-align:left;">Возвращает перечень опубликованных и черновых магазинов</td></tr><tr><td style="text-align:left;">Чтение главного баннера</td><td style="text-align:left;"><code>web_store_get_home</code></td><td style="text-align:left;">Считывает структуру макета, кнопки и активные слайды</td></tr><tr><td style="text-align:left;">Обновление заголовков баннера</td><td style="text-align:left;"><code>web_store_update_home_banner</code></td><td style="text-align:left;">Перезаписывает главный заголовок и подзаголовок первого экрана</td></tr><tr><td style="text-align:left;">Изменение слайдов и верстки</td><td style="text-align:left;"><code>web_store_update_home_banner_settings</code></td><td style="text-align:left;">Изменяет состав слайдов, порядок кнопок и макет</td></tr><tr><td style="text-align:left;">Чтение промобаннера</td><td style="text-align:left;"><code>web_store_get_home_promo</code></td><td style="text-align:left;">Считывает параметры рекламной растяжки</td></tr><tr><td style="text-align:left;">Обновление промобаннера</td><td style="text-align:left;"><code>web_store_update_home_promo</code></td><td style="text-align:left;">Изменяет текст, бейдж и ссылку на кнопку акции</td></tr><tr><td style="text-align:left;">Чтение структуры навигации</td><td style="text-align:left;"><code>web_store_get_home_navigation</code></td><td style="text-align:left;">Возвращает порядок смысловых блоков и состав меню</td></tr><tr><td style="text-align:left;">Изменение порядка секций</td><td style="text-align:left;"><code>web_store_update_home_navigation</code></td><td style="text-align:left;">Меняет местами этапы работы, товары, отзывы и контакты</td></tr><tr><td style="text-align:left;">Чтение этапов работы</td><td style="text-align:left;"><code>web_store_get_home_process</code></td><td style="text-align:left;">Возвращает перечень шагов производственного процесса</td></tr><tr><td style="text-align:left;">Изменение этапов работы</td><td style="text-align:left;"><code>web_store_update_home_process</code></td><td style="text-align:left;">Обновляет нумерацию, заголовки и описания шагов</td></tr><tr><td style="text-align:left;">Создание новой веб-страницы</td><td style="text-align:left;"><code>web_store_create_page</code></td><td style="text-align:left;">Создает информационный раздел в формате Markdown</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Импорт графики внешним агентом</p><p>При работе с изображениями укажите доверенную папку с исходными файлами в поле <strong>«Разрешенные директории»</strong> настроек ассистента. При вызове команды агент передает полный путь к локальному файлу, система валидирует безопасность пути и автоматически связывает оптимизированную графику с нужной витриной.</p></div><h3 id="_8-режим-агента-пк-и-четырехуровневая-защита" tabindex="-1">8. Режим агента ПК и четырёхуровневая защита <a class="header-anchor" href="#_8-режим-агента-пк-и-четырехуровневая-защита" aria-label="Permalink to &quot;8. Режим агента ПК и четырёхуровневая защита&quot;">​</a></h3><p>Для безопасного взаимодействия ассистента с операционной системой и внешними утилитами в ОмниКрафт ЕРП встроен четырёхуровневый защитный шлюз:</p><ul><li><strong>Тумблер «Режим агента ПК»:</strong> По умолчанию строго выключен. Программа блокирует любые обращения к системным командам и файлам за пределами программы.</li><li><strong>Белый список каталогов:</strong> Мастер может указать перечень доверенных папок (например, <code>C:\\Отчеты; D:\\Чертежи</code>), ограничив операции сохранения и чтения только этими границами. Прямой доступ к базам данных (<code>*.db</code>, <code>*.sqlite</code>) и файлам секретов (<code>.env</code>) аппаратно блокируется ядром.</li><li><strong>Матрица авторизации действий:</strong><ul><li><strong>Класс 1 (Чтение ERP):</strong> Просмотр складских остатков, расчет себестоимости и формирование отчетов — выполняются автоматически без пауз.</li><li><strong>Класс 2 (Мутации ERP):</strong> Списание сырья, проведение партий, оформление чеков — отображают интерактивную карточку действия с кнопками <strong>«Выполнить»</strong> и <strong>«Отклонить»</strong>.</li><li><strong>Класс 3 (Файловая система и оборудование):</strong> Запись отчетов на диск, чтение внешних накладных, отправка этикеток на печать — требуют подтверждения целевого каталога или принтера в модальном окне.</li><li><strong>Класс 4 (Системные команды ОС):</strong> Запуск исполняемых файлов и команд терминала — вызывают красное предупреждающее окно безопасности с показом полного текста команды, валидацией политики нулевого разрушения и трёхсекундной аппаратной задержкой кнопки подтверждения для защиты от случайного нажатия.</li></ul></li></ul><h3 id="_9-инспектор-промптов-и-библиотека-навыков-ии" tabindex="-1">9. Инспектор промптов и библиотека навыков ИИ <a class="header-anchor" href="#_9-инспектор-промптов-и-библиотека-навыков-ии" aria-label="Permalink to &quot;9. Инспектор промптов и библиотека навыков ИИ&quot;">​</a></h3><p>Единый инженерный пульт управления сценариями и системными инструкциями доступен через верхнее меню <strong>«Справка» ➔ «Системные реестры...»</strong>. Окно <strong>«Системные реестры: Навыки и промпты ИИ»</strong> обеспечивает полный контроль над поведением ассистента на всех уровнях работы программы.</p><h4 id="цеховая-задача-и-архитектура-промптов" tabindex="-1">Цеховая задача и архитектура промптов <a class="header-anchor" href="#цеховая-задача-и-архитектура-промптов" aria-label="Permalink to &quot;Цеховая задача и архитектура промптов&quot;">​</a></h4><p>Для предсказуемой работы в цехе мастер должен понимать, какие инструкции определяют поведение ассистента на каждом рабочем экране. Иерархия промптов разделена на 4 четких уровня (L0–L3):</p><ol><li><strong>L0 (Ядро системы):</strong> неизменяемые законы целостности данных, защита локальных файлов и жесткие формулы учета (МАК, ФИФО, целочисленный масштаб).</li><li><strong>L1 (Профиль мастерской):</strong> глобальная роль старшего мастера-наставника, тон общения и отраслевой контекст предприятия.</li><li><strong>L2 (Пространства):</strong> специализация под конкретный вид деятельности (Бизнес, Сервис, Торговля, Мой капитал).</li><li><strong>L3 (Вкладки и экраны):</strong> предметные инструкции для каждого инструмента (Склад сырья, Верстак, Калькулятор, Продажи, ДДС).</li></ol><h4 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h4><p>Инспектор вызывается из любого экрана программы через строку меню заголовка окна.</p><h4 id="пошаговыи-порядок-инспекции-промптов-и-настроики-навыков" tabindex="-1">Пошаговый порядок инспекции промптов и настройки навыков <a class="header-anchor" href="#пошаговыи-порядок-инспекции-промптов-и-настроики-навыков" aria-label="Permalink to &quot;Пошаговый порядок инспекции промптов и настройки навыков&quot;">​</a></h4><ol><li><strong>Вызов окна инспектора:</strong> В шапке окна нажмите кнопку меню <strong>«Справка»</strong> (иконка знака вопроса) и выберите пункт <strong>«Системные реестры...»</strong>. На экране откроется двухпанельный пульт управления.</li><li><strong>Навигация по системному дереву (левая панель):</strong><ul><li>Раздел <strong>«Программа»</strong>: просмотр неизменяемого ядра <code>L0</code>, глобального профиля <code>L1</code> и общих системных инструкций;</li><li>Раздел <strong>«Пространства»</strong>: переключение между отраслевыми контурами (<code>Бизнес</code>, <code>Сервис</code>, <code>Торговля</code>, <code>Мой капитал</code>);</li><li>Раздел <strong>«Вкладки и модули»</strong>: выбор целевого рабочего экрана (<code>Склад сырья</code>, <code>Мастерская</code>, <code>Калькулятор</code>, <code>Верстак</code>, <code>Витрина</code>, <code>Продажи</code>, <code>ДДС</code>, <code>Баланс и капитал</code>, <code>Сводка и аналитика</code>, <code>Настройки</code>, <code>Мой капитал</code>, <code>Партнеры</code>).</li></ul></li><li><strong>Инспекция текста системного промпта (правая панель):</strong><ul><li>При клике на любой узел дерева в блоке <strong>«Системный промпт»</strong> выводится актуальный текст директивы для выбранного уровня в моноширинном поле просмотра;</li><li>Текст доступен для свободного чтения и копирования, исключая эффект «черного ящика».</li></ul></li><li><strong>Управление библиотекой навыков:</strong><ul><li>В блоке <strong>«Библиотека навыков уровня»</strong> отображаются готовые сценарии, закрепленные за текущим экраном;</li><li>Синий бейдж <strong>«Встроенный»</strong> обозначает заводские сценарии программы, зеленый <strong>«Пользовательский»</strong> — сценарии, добавленные мастером;</li><li>Переключатель активности позволяет временно отключать неиспользуемые навыки для разгрузки контекстного окна модели;</li><li>Иконка карандаша открывает редактирование пользовательского сценария, а иконка корзины — его удаление.</li></ul></li><li><strong>Создание собственного навыка:</strong><ul><li>Нажмите кнопку <strong>«+ Новый навык»</strong> внизу списка навыков;</li><li>В модальном окне заполните реквизиты: <ul><li><strong>«Название навыка»</strong>: краткое имя сценария для отображения в интерфейсе;</li><li><strong>«Область видимости (Scope)»</strong>: привязка к конкретному экрану или глобальному контексту;</li><li><strong>«Иконка»</strong>: кодовое имя символа Material Icons;</li><li><strong>«Краткое описание»</strong>: цеховое назначение инструмента;</li><li><strong>«Промпт / Сценарий»</strong>: пошаговая инструкция для нейросети с описанием формата результата;</li></ul></li><li>Нажмите кнопку <strong>«Сохранить»</strong>. Навык появится в реестре и станет доступен в виде быстрой кнопки-чипса на рабочем столе ассистента.</li></ul></li><li><strong>Экспорт архитектурной карты в Markdown:</strong><ul><li>В правом верхнем углу окна нажмите кнопку <strong>«Экспорт карты (.md)»</strong>;</li><li>Программа сформирует полный структурированный отчет по всей иерархии L0–L3, системным промптам и активным навыкам и скопирует его в буфер обмена с подтверждающим уведомлением;</li><li>Полученную карту можно передать во внешнюю среду разработки или использовать для тонкой калибровки локальной нейросети.</li></ul></li><li><strong>Закрытие окна:</strong> Нажмите кнопку <strong>«Закрыть»</strong> для возврата к текущей рабочей задаче.</li></ol><hr><h2 id="аварииное-обслуживание-и-сброс-данных" tabindex="-1">Аварийное обслуживание и сброс данных <a class="header-anchor" href="#аварииное-обслуживание-и-сброс-данных" aria-label="Permalink to &quot;Аварийное обслуживание и сброс данных&quot;">​</a></h2><p>В нижней части вкладки «Основные» расположен блок инструментов для аварийного вмешательства в базу данных. Эти операции предназначены для исключительных ситуаций и требуют осознанного применения.</p><h3 id="сброс-учета-очистка-операционнои-истории" tabindex="-1">Сброс учета (Очистка операционной истории) <a class="header-anchor" href="#сброс-учета-очистка-операционнои-истории" aria-label="Permalink to &quot;Сброс учета (Очистка операционной истории)&quot;">​</a></h3><p>Инструмент очищает операционную историю бизнеса, полностью сохраняя инфраструктуру мастерской. Он незаменим, когда мастер закончил тестовое освоение программы с фиктивными чеками и готов перейти к реальному учету:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Категория</th><th style="text-align:left;">Что происходит с данными</th><th style="text-align:left;">Содержимое</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Журналы операций</strong></td><td style="text-align:left;">Полное удаление записей</td><td style="text-align:left;">История чеков и розничных продаж, складские приходные и расходные накладные, журнал кассовых операций ДДС, производственные очереди на верстаке, партии списания</td></tr><tr><td style="text-align:left;"><strong>Текущие остатки</strong></td><td style="text-align:left;">Обнуление показателей</td><td style="text-align:left;">Количественные остатки сырья на складе, остатки готовых изделий, сальдо кассы и расчетных счетов, накопленная себестоимость</td></tr><tr><td style="text-align:left;"><strong>Инфраструктура цеха</strong></td><td style="text-align:left;"><strong>100% сохранение</strong></td><td style="text-align:left;">Станки и оборудование в «Мастерской», справочники номенклатуры сырья, шаблоны изделий и технологические рецепты, категории расходов, поставщики и клиенты</td></tr></tbody></table><p>Перед очисткой программа автоматически создает теневую резервную копию базы данных. После нажатия кнопки <strong>«Сбросить учет»</strong> ОмниКрафт ЕРП предложит выполнить перезагрузку, после чего вы получите чистую мастерскую, готовую к инвентаризации стартовых запасов.</p><h3 id="полныи-сброс-до-заводских-настроек" tabindex="-1">Полный сброс до заводских настроек <a class="header-anchor" href="#полныи-сброс-до-заводских-настроек" aria-label="Permalink to &quot;Полный сброс до заводских настроек&quot;">​</a></h3><p>Критическая операция, безвозвратно удаляющая все данные локальной базы.</p><ul><li>База данных полностью очищается: удаляются номенклатура, оборудование, клиенты, рецепты, настройки и активный лицензионный ключ.</li><li>Программа возвращается к состоянию чистого первого запуска.</li></ul><div class="danger custom-block"><p class="custom-block-title">Внимание: Риск полной утраты данных</p><p>Перед выполнением полного сброса <strong>обязательно</strong> сделайте ручной экспорт резервной копии через меню <strong>«Файл» ➔ «Экспорт данных» ➔ «Резервная копия базы (.db)»</strong> и сохраните ваш лицензионный ключ в надежном месте. Без файла резервной копии восстановить структуру мастерской невозможно.</p></div><hr><h2 id="автоматическии-перезапуск-программы" tabindex="-1">Автоматический перезапуск программы <a class="header-anchor" href="#автоматическии-перезапуск-программы" aria-label="Permalink to &quot;Автоматический перезапуск программы&quot;">​</a></h2><p>Любые изменения системных параметров (смена языка, выбор темы, переключение каналов обновлений или сброс учета) требуют переинициализации оперативной памяти.</p><p>После сохранения настроек программа открывает подтверждающий диалог с предложением выполнить перезапуск немедленно либо отложить его до завершения текущей сессии. При автоматическом перезапуске ОмниКрафт ЕРП сохраняет экранные координаты и размер окна, возвращая мастера ровно на ту рабочую позицию, где было открыто окно настроек.</p>',78))])}const y=l(g,[["render",h]]);export{x as __pageData,y as default};
